// android.mjs — THE PHONE APP ON AN EMULATOR, from the command line: set the SDK up, boot a device, build and install
// the app, and point Playwright or a screenshot at it. A self-tool (skill: .claude/skills/phone/SKILL.md), OPTIONAL
// like everything mobile: nothing in `npm test` or the chat suites needs it (CONTRIBUTING.md, "The mobile clients").
// The app is `mobile/` (docs/spec/NATIVE_SHELL.md); its gradle project is generated by `expo prebuild`, never committed.
//
//   node scripts/android.mjs doctor          what is installed and what is missing, and the command for each
//   node scripts/android.mjs setup           the SDK packages and one emulator (`wml-phone`), once
//   node scripts/android.mjs boot [--window] start the emulator (headless unless --window) and wait for it to boot
//   node scripts/android.mjs install [--demo] build the page, sync it into the app, build the APK, install it
//                                            (`--demo` carries the fake-host demo page instead of this device's account)
//   node scripts/android.mjs launch          start the app (cold: it is stopped first)
//   node scripts/android.mjs shot [file]     a screenshot of the device (default test-results/android.png)
//   node scripts/android.mjs flows [--report f] [file…]  run Maestro flows (default: every tests/mobile/*.yaml) against
//                                            the device; `--report` also writes a JUnit report to f
//   node scripts/android.mjs drag <from> <to> [--record file.mp4]
//                                            long-press the element showing <from>, drag it onto <to>, release: the
//                                            gesture Maestro has no step for (a list row put in a new place)
//   node scripts/android.mjs order <text…>   exit 1 unless these texts are on screen, top to bottom, in this order
//   node scripts/android.mjs stop            shut the emulator down
//
// Every step works against a real phone too, when it is the only device adb sees (USB debugging on); `boot` is then
// unnecessary. The SDK is the command-line one (`brew install --cask android-commandlinetools`), not Android Studio.

import { spawn, spawnSync } from "node:child_process";
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { ensurePrebuild } from "./mobile-prebuild.mjs";

const HOME = process.env.ANDROID_HOME || process.env.ANDROID_SDK_ROOT || "/opt/homebrew/share/android-commandlinetools";
const API = 35;
/** The emulator's system image. Newer than the build's API level on purpose: an image carries the WebView it shipped with
 *  and cannot update it (no Play Store), and API 35's is Chrome 124, which has no Ed25519 or X25519 in WebCrypto. The
 *  hub's crypto needs both (Chrome 137+); a real phone updates its WebView from the Play Store. */
const IMAGE_API = "37.0";
/** The image's ABI is the HOST's: an arm64 image runs only on Apple silicon, and a Linux CI runner needs x86_64 (KVM). */
const IMAGE_ABI = process.arch === "arm64" ? "arm64-v8a" : "x86_64";
const IMAGE = `system-images;android-${IMAGE_API};google_apis;${IMAGE_ABI}`;
const PACKAGES = ["platform-tools", "emulator", `platforms;android-${API}`, "build-tools;35.0.0", IMAGE];
const AVD = "wml-phone";
const APP = "dev.wander.windowml";

/** The JDK gradle is run with: 21, which React Native's gradle plugin accepts and a newer default does not. */
function javaHome() {
    const r = spawnSync("/usr/libexec/java_home", ["-v", "21"], { encoding: "utf8" });
    return r.status === 0 ? r.stdout.trim() : process.env.JAVA_HOME;
}
const env = { ...process.env, ANDROID_HOME: HOME, ANDROID_SDK_ROOT: HOME, ...(javaHome() ? { JAVA_HOME: javaHome() } : {}) };
const bin = {
    adb: path.join(HOME, "platform-tools/adb"),
    emulator: path.join(HOME, "emulator/emulator"),
    sdkmanager: "sdkmanager",
    avdmanager: "avdmanager",
};

/** Run a command to completion, inheriting the terminal; exit with its status when it fails. */
function run(cmd, args, opts = {}) {
    const r = spawnSync(cmd, args, { stdio: "inherit", env, ...opts });
    if (r.status !== 0) { console.error(`✗ ${cmd} ${args.join(" ")} exited ${r.status}`); process.exit(r.status ?? 1); }
}
/** Run a command and return its stdout (empty on failure). */
const out = (cmd, args) => spawnSync(cmd, args, { encoding: "utf8", env }).stdout?.trim() ?? "";
/** The Maestro CLI: on the PATH, or where its release zip unpacks (`~/.maestro/maestro/bin`). */
const maestro = () => out("which", ["maestro"]) || [path.join(process.env.HOME ?? "", ".maestro/maestro/bin/maestro")].find((p) => existsSync(p)) || "";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function doctor() {
    const checks = [
        ["JDK 21", !!javaHome(), "brew install --cask temurin@21"],
        ["sdkmanager", !!out("which", ["sdkmanager"]), "brew install --cask android-commandlinetools"],
        ["adb (platform-tools)", existsSync(bin.adb), "node scripts/android.mjs setup"],
        ["emulator", existsSync(bin.emulator), "node scripts/android.mjs setup"],
        [`system image (API ${IMAGE_API}, ${IMAGE_ABI})`, existsSync(path.join(HOME, "system-images", `android-${IMAGE_API}`)), "node scripts/android.mjs setup"],
        [`emulator "${AVD}"`, out(bin.emulator, ["-list-avds"]).split("\n").includes(AVD), "node scripts/android.mjs setup"],
        ["Maestro (mobile.dev)", !!maestro(), "the release zip into ~/.maestro (CONTRIBUTING.md); NOT the `maestro` cask, a different app"],
    ];
    for (const [name, ok, fix] of checks) console.log(`${ok ? "✓" : "✗"} ${name}${ok ? "" : `   → ${fix}`}`);
    const devices = existsSync(bin.adb) ? out(bin.adb, ["devices"]).split("\n").slice(1).filter(Boolean) : [];
    console.log(devices.length ? `devices: ${devices.join(", ")}` : "devices: none (boot one, or plug a phone in with USB debugging on)");
}

function setup() {
    spawnSync("sh", ["-c", `yes | sdkmanager --licenses >/dev/null`], { env, stdio: "ignore" });
    run(bin.sdkmanager, ["--install", ...PACKAGES]);
    // An emulator on an older image is recreated: the image decides the WebView, and the WebView decides the crypto.
    const ini = path.join(process.env.HOME ?? "", ".android", "avd", `${AVD}.avd`, "config.ini");
    if (existsSync(ini) && !readFileSync(ini, "utf8").includes(`android-${IMAGE_API}`)) run(bin.avdmanager, ["delete", "avd", "-n", AVD]);
    if (!out(bin.emulator, ["-list-avds"]).split("\n").includes(AVD)) {
        run(bin.avdmanager, ["create", "avd", "-n", AVD, "-k", IMAGE, "-d", "pixel_7"], { input: "no\n", stdio: ["pipe", "inherit", "inherit"] });
    }
    console.log(`✓ SDK packages and the "${AVD}" emulator are in place`);
}

async function boot(window) {
    if (out(bin.adb, ["devices"]).includes("emulator-")) { console.log("an emulator is already running"); return; }
    // Linux without a display (a CI runner) has no GPU to hand the emulator: render in software, or it never boots.
    const gpu = !window && process.platform === "linux" ? ["-gpu", "swiftshader_indirect"] : [];
    const args = ["-avd", AVD, "-no-snapshot-save", "-no-boot-anim", ...(window ? [] : ["-no-window", "-no-audio"]), ...gpu];
    const child = spawn(bin.emulator, args, { env, detached: true, stdio: "ignore" });
    child.unref();
    run(bin.adb, ["wait-for-device"]);
    // A cold boot on a CI runner takes several minutes, so the wait is longer there (`BOOT_TIMEOUT_S`).
    const limit = Number(process.env.BOOT_TIMEOUT_S ?? 120);
    for (let i = 0; i < limit; i++) {
        if (out(bin.adb, ["shell", "getprop", "sys.boot_completed"]) === "1") { console.log("✓ booted"); return; }
        await sleep(1000);
    }
    console.error(`✗ the emulator did not finish booting in ${limit} s`);
    process.exit(1);
}

/**
 * The app: the page built and synced into it, then a release APK (the JS bundled in, so no Metro) and installed. The
 * previous JS bundle is deleted first: gradle tracks only files under mobile/, so a change to the shared src/native/
 * would otherwise leave the old bundle in place and the build would look like it did nothing.
 */
function install() {
    run("node", ["scripts/build-web.mjs"]);
    run("node", ["mobile/scripts/sync-embed.mjs", ...(process.argv.includes("--demo") ? ["--demo"] : [])]);
    ensurePrebuild("android", run);
    spawnSync("rm", ["-rf", "mobile/android/app/build/generated/assets/react/release"]);
    // Built for the device it goes on: the release default is arm64-v8a alone (app.json, expo-build-properties), which an
    // x86_64 emulator on an Intel Mac cannot run. One ABI is also a quarter of the native build.
    const abi = out(bin.adb, ["shell", "getprop", "ro.product.cpu.abi"]).trim();
    // NOT `--quiet`: it hides the REASON a build failed. A resource clash printed nothing but "exited 1", and the
    // error ("Found item Style/AppTheme more than one time") only appeared on a second, verbose run by hand.
    // No lint: a RELEASE build runs "lint vital" over every module (about 90 s in CI), and this APK is for a device
    // under test, never published. The published one is `tests.yml`'s `mobile-android`, which keeps it.
    const noLint = ["lintVitalRelease", "lintVitalAnalyzeRelease", "lintVitalReportRelease"].flatMap((t) => ["-x", t]);
    run("./gradlew", ["assembleRelease", ...noLint, ...(abi ? [`-PreactNativeArchitectures=${abi}`] : [])], { cwd: "mobile/android" });
    run(bin.adb, ["install", "-r", "mobile/android/app/build/outputs/apk/release/app-release.apk"]);
    console.log(`✓ installed ${APP}`);
}

function launch() {
    run(bin.adb, ["shell", "am", "force-stop", APP]);
    // By its activity, not `monkey`, whose launcher lookup exits 251 on a fresh emulator image.
    run(bin.adb, ["shell", "am", "start", "-W", "-n", `${APP}/.MainActivity`], { stdio: "ignore" });
    console.log(`✓ launched ${APP}`);
}

function shot(file = "test-results/android.png") {
    mkdirSync(path.dirname(file), { recursive: true });
    const r = spawnSync(bin.adb, ["exec-out", "screencap", "-p"], { env, maxBuffer: 64 << 20 });
    if (r.status !== 0 || !r.stdout?.length) { console.error("✗ no screenshot: is a device connected?"); process.exit(1); }
    writeFileSync(file, r.stdout);
    console.log(`✓ ${file}`);
}

/**
 * Maestro against the connected device: the given flows, or every one in tests/mobile/. `--report <file>` also writes
 * a JUnit report, which is how CI checks that every flow it named actually ran.
 */
function flows(argv) {
    const at = argv.indexOf("--report");
    const report = at >= 0 ? ["--format", "junit", "--output", argv[at + 1]] : [];
    const files = at >= 0 ? argv.filter((_, i) => i !== at && i !== at + 1) : argv;
    // Maestro will not create the report's folder, and fails the whole run on it after every flow passed.
    if (at >= 0) mkdirSync(path.dirname(argv[at + 1]), { recursive: true });
    const m = maestro();
    if (!m) { console.error("✗ Maestro is not installed (node scripts/android.mjs doctor)"); process.exit(1); }
    const targets = files.length ? files : ["tests/mobile"];
    // A fresh emulator's library is empty and demo-attach.yaml picks two photos from it. Maestro's `addMedia` cannot
    // reach a fixture when several flows run at once ("not found in workspace"), so they are pushed here and scanned.
    for (const f of readdirSync("tests/mobile").filter((n) => /^photo-.*\.png$/.test(n))) {
        run(bin.adb, ["push", path.join("tests/mobile", f), `/sdcard/Pictures/${f}`]);
        run(bin.adb, ["shell", "am", "broadcast", "-a", "android.intent.action.MEDIA_SCANNER_SCAN_FILE", "-d", `file:///sdcard/Pictures/${f}`]);
    }
    // No analytics prompt: its first-run banner made the first invocation exit 1 with every flow unrun.
    run(m, ["test", ...report, ...targets], { env: { ...env, PATH: `${path.dirname(bin.adb)}:${process.env.PATH}`, MAESTRO_CLI_NO_ANALYTICS: "1", MAESTRO_CLI_ANALYSIS_NOTIFICATION_DISABLED: "true" } });
}

/** Every element on screen that shows text, with its box, from the device's accessibility dump. */
function onScreen() {
    const xml = spawnSync(bin.adb, ["exec-out", "uiautomator", "dump", "/dev/tty"], { env, encoding: "utf8", maxBuffer: 64 << 20 }).stdout ?? "";
    const ent = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'" };
    return [...xml.matchAll(/text="([^"]*)"[^>]*?bounds="\[(\d+),(\d+)\]\[(\d+),(\d+)\]"/g)]
        .filter((m) => m[1])
        .map((m) => ({ text: m[1].replace(/&(\w+);/g, (_, e) => ent[e] ?? `&${e};`), x: (+m[2] + +m[4]) >> 1, y: (+m[3] + +m[5]) >> 1 }));
}
/** The element showing exactly `text`; the run ends, naming what IS on screen, when there is none. */
function find(text) {
    const all = onScreen();
    const hit = all.find((e) => e.text === text);
    if (!hit) { console.error(`✗ nothing on screen reads "${text}". On screen: ${all.map((e) => JSON.stringify(e.text)).join(", ")}`); process.exit(1); }
    return hit;
}

/**
 * Long-press the element showing `from` and drag it onto `to`, the way a thumb does: down, hold past the long press,
 * move in small steps, a beat, up. `input draganddrop` was tried first and moved a React Native row about a third as
 * far as the finger went; `input motionevent` delivers every step.
 */
async function drag(from, to, record) {
    const a = find(from), b = find(to);
    // Aim just past the target's middle, so the dragged row's leading edge has crossed it whichever way it goes.
    const end = b.y + (b.y < a.y ? -4 : 4);
    const step = end < a.y ? -20 : 20;
    const ys = [];
    for (let y = a.y + step; step < 0 ? y > end : y < end; y += step) ys.push(y);
    ys.push(end);
    let rec;
    if (record) { rec = spawn(bin.adb, ["shell", "screenrecord", "--time-limit", "6", "/sdcard/wml-drag.mp4"], { env, stdio: "ignore" }); await sleep(1000); }
    const moves = ys.map((y) => `input motionevent MOVE ${a.x} ${y}`).join("; ");
    run(bin.adb, ["shell", `input motionevent DOWN ${a.x} ${a.y}; sleep 0.7; ${moves}; sleep 0.3; input motionevent UP ${a.x} ${end}`]);
    if (rec) {
        await new Promise((r) => rec.on("exit", r));
        mkdirSync(path.dirname(record), { recursive: true });
        run(bin.adb, ["pull", "/sdcard/wml-drag.mp4", record], { stdio: "ignore" });
        console.log(`✓ recorded ${record}`);
    }
    await sleep(800);   // the drop settles before anything reads the screen
    console.log(`✓ dragged "${from}" onto "${to}"`);
}

/** Exit 1 unless every text is on screen and they read top to bottom in the order given. */
function order(texts) {
    const all = onScreen();
    const at = texts.map((t) => ({ t, y: all.find((e) => e.text === t)?.y }));
    for (const { t, y } of at) console.log(`  ${y ?? "—"}\t${t}`);
    const ok = at.every((e) => e.y != null) && at.every((e, i) => i === 0 || e.y > at[i - 1].y);
    console.log(ok ? "✓ in order" : "✗ not in this order");
    if (!ok) process.exit(1);
}

const [cmd, arg] = process.argv.slice(2);
switch (cmd) {
    case "doctor": doctor(); break;
    case "setup": setup(); break;
    case "boot": await boot(process.argv.includes("--window")); break;
    case "install": install(); break;
    case "launch": launch(); break;
    case "shot": shot(arg); break;
    case "flows": flows(process.argv.slice(3)); break;
    case "drag": {
        const [from, to] = process.argv.slice(3).filter((x, i, xs) => !x.startsWith("--") && xs[i - 1] !== "--record");
        const r = process.argv.indexOf("--record");
        if (!from || !to) { console.error("usage: node scripts/android.mjs drag <from text> <to text> [--record file.mp4]"); process.exit(2); }
        await drag(from, to, r > 0 ? process.argv[r + 1] : undefined);
        break;
    }
    case "order": order(process.argv.slice(3)); break;
    case "stop": run(bin.adb, ["emu", "kill"]); break;
    default:
        console.error("usage: node scripts/android.mjs <doctor|setup|boot [--window]|install|launch|shot [file]|flows [--report file] [file…]|drag <from> <to> [--record f]|order <text…>|stop>");
        process.exit(2);
}
